/root/.pochi/bin/agent-browser eval "$(cat <<'EOF'
(async () => {
  const results = [];

  function assert(condition, message) {
    results.push({
      pass: !!condition,
      message: message,
      actual: condition ? 'true' : 'false'
    });
  }

  function assertDeepEqual(actual, expected, message) {
    const actualStr = JSON.stringify(actual);
    const expectedStr = JSON.stringify(expected);
    const pass = actualStr === expectedStr;
    results.push({
      pass,
      message,
      actual: actualStr,
      expected: expectedStr
    });
  }

  // 1. Clear localStorage and Capacitor Preferences
  localStorage.clear();

  // Test Case 1: Normal Migration
  try {
    localStorage.setItem('legacy:theme', 'dark');
    localStorage.setItem('legacy:user', 'alice');
    localStorage.setItem('other_key', 'dont_touch');

    const report1 = await window.migrateStorage();

    // Sort migrated and skipped arrays to ensure order-independent comparison
    if (report1 && Array.isArray(report1.migrated)) report1.migrated.sort();
    if (report1 && Array.isArray(report1.skipped)) report1.skipped.sort();

    const expectedReport1 = { alreadyCompleted: false, migrated: ['theme', 'user'], skipped: [] };
    expectedReport1.migrated.sort();
    expectedReport1.skipped.sort();

    assertDeepEqual(report1, expectedReport1, 'Test Case 1: Report matches expected');

    assert(localStorage.getItem('legacy:theme') === null, 'Test Case 1: legacy:theme is removed');
    assert(localStorage.getItem('legacy:user') === null, 'Test Case 1: legacy:user is removed');
    assert(localStorage.getItem('other_key') === 'dont_touch', 'Test Case 1: other_key is untouched');
    assert(localStorage.getItem('CapacitorStorage.theme') === 'dark', 'Test Case 1: CapacitorStorage.theme is dark');
    assert(localStorage.getItem('CapacitorStorage.user') === 'alice', 'Test Case 1: CapacitorStorage.user is alice');
    assert(localStorage.getItem('CapacitorStorage.migration_completed') === 'true', 'Test Case 1: migration_completed is true');
  } catch (e) {
    assert(false, 'Test Case 1 failed with error: ' + e.message + '\n' + e.stack);
  }

  // Test Case 2: Idempotency
  try {
    const report2 = await window.migrateStorage();
    if (report2 && Array.isArray(report2.migrated)) report2.migrated.sort();
    if (report2 && Array.isArray(report2.skipped)) report2.skipped.sort();

    const expectedReport2 = { alreadyCompleted: true, migrated: [], skipped: [] };
    assertDeepEqual(report2, expectedReport2, 'Test Case 2: Report matches expected');
  } catch (e) {
    assert(false, 'Test Case 2 failed with error: ' + e.message + '\n' + e.stack);
  }

  // Test Case 3: Conflict Resolution
  try {
    localStorage.clear();
    localStorage.setItem('CapacitorStorage.theme', 'light');
    localStorage.setItem('legacy:theme', 'dark');
    localStorage.setItem('legacy:user', 'bob');

    const report3 = await window.migrateStorage();
    if (report3 && Array.isArray(report3.migrated)) report3.migrated.sort();
    if (report3 && Array.isArray(report3.skipped)) report3.skipped.sort();

    const expectedReport3 = { alreadyCompleted: false, migrated: ['user'], skipped: ['theme'] };
    expectedReport3.migrated.sort();
    expectedReport3.skipped.sort();

    assertDeepEqual(report3, expectedReport3, 'Test Case 3: Report matches expected');

    assert(localStorage.getItem('legacy:theme') === 'dark', 'Test Case 3: legacy:theme still exists and is dark');
    assert(localStorage.getItem('legacy:user') === null, 'Test Case 3: legacy:user is removed');
    assert(localStorage.getItem('CapacitorStorage.theme') === 'light', 'Test Case 3: CapacitorStorage.theme is still light');
    assert(localStorage.getItem('CapacitorStorage.user') === 'bob', 'Test Case 3: CapacitorStorage.user is bob');
    assert(localStorage.getItem('CapacitorStorage.migration_completed') === 'true', 'Test Case 3: migration_completed is true');
  } catch (e) {
    assert(false, 'Test Case 3 failed with error: ' + e.message + '\n' + e.stack);
  }

  return results;
})()
EOF
)"

